import hashlib

SYSTEMS = ["llm_only", "tfidf_rag", "graph_rag"]


def score_answers(cases, answers, judge, apply_overrides=False):
    case_by_id = {case["id"]: case for case in cases}
    seen = set()

    for answer in answers:
        answer_id = answer.get("id")
        system = answer.get("system")

        if system not in SYSTEMS:
            raise ValueError("unknown system: %r" % (system,))
        if answer_id not in case_by_id:
            raise ValueError("extra answer for unknown case: %r" % (answer_id,))

        key = (answer_id, system)
        if key in seen:
            raise ValueError("duplicate answer: %r" % (key,))
        seen.add(key)

    for case in cases:
        for system in SYSTEMS:
            if (case["id"], system) not in seen:
                raise ValueError(
                    "missing answer for case %r system %r" % (case["id"], system)
                )

    rows = []
    for answer in answers:
        case = case_by_id[answer["id"]]
        score = judge(case, answer)

        if apply_overrides:
            override = case.get("legacy_override")
            if override:
                stored_sha = override.get("answer_sha256")
                current_sha = hashlib.sha256(
                    answer["answer"].encode("utf-8")
                ).hexdigest()
                if stored_sha == current_sha:
                    for key, value in override.items():
                        if key != "answer_sha256":
                            score[key] = value

        if "total" not in score:
            score["total"] = sum(
                value
                for value in score.values()
                if isinstance(value, (int, float)) and not isinstance(value, bool)
            )

        rows.append({**answer, **score, "adjudication": "scored"})

    return rows
